local EAT_ANIM = { dict = 'mp_player_inteat@burger', clip = 'mp_player_int_eat_burger_fp', flag = 49 }
local DRINK_ANIM_BOTTLE = { dict = 'mp_player_intdrink', clip = 'loop_bottle', flag = 49 }
local DRINK_ANIM_CUP = { dict = 'amb@world_human_drinking@coffee@male@idle_a', clip = 'idle_c', flag = 49 }
local DRINK_ANIM_BEER = { dict = 'amb@world_human_drinking@beer@male@idle_a', clip = 'idle_c', flag = 49 }
--- cylex + sph custom prop tutuşları (rotOrder 0 — cylex/emote ile aynı)
local DRINK_PROP = {
    --- sph_butterbeerstein2 / sph_we_rollup_mug — mp_player_intdrink
    stein  = { bone = 18905, pos = vec3(0.01, 0.01, 0.06), rot = vec3(5.0, 5.0, -180.5), rotOrder = 0 },
    mug    = { bone = 18905, pos = vec3(0.02, 0.02, 0.05), rot = vec3(8.0, -12.0, -175.0), rotOrder = 0 },
    jug    = { bone = 18905, pos = vec3(0.13, 0.03, 0.05), rot = vec3(-110.0, -47.0, 7.0), rotOrder = 0 },
    cup    = { bone = 28422, pos = vec3(0.0, 0.0, 0.0), rot = vec3(0.0, 0.0, 130.0), rotOrder = 0 },
    bottle = { bone = 28422, pos = vec3(0.0, 0.0, 0.06), rot = vec3(0.0, 15.0, 0.0), rotOrder = 0 },
    water  = { bone = 28422, pos = vec3(0.01, -0.01, -0.06), rot = vec3(0.0, 0.0, 0.0), rotOrder = 0 },
}
local DRINK_HOLD = DRINK_PROP.stein.pos
local DRINK_ROT = DRINK_PROP.stein.rot

local function resolveDrink(style)
    style = style or 'stein'
    if style == 'cup' or style == 'tea' then
        local p = DRINK_PROP.cup
        return DRINK_ANIM_CUP, p.bone, p.pos, p.rot, p.rotOrder
    end
    if style == 'mug' then
        local p = DRINK_PROP.mug
        return DRINK_ANIM_BOTTLE, p.bone, p.pos, p.rot, p.rotOrder
    end
    if style == 'jug' then
        local p = DRINK_PROP.jug
        return DRINK_ANIM_BOTTLE, p.bone, p.pos, p.rot, p.rotOrder
    end
    if style == 'bottle' then
        local p = DRINK_PROP.bottle
        return DRINK_ANIM_BEER, p.bone, p.pos, p.rot, p.rotOrder
    end
    if style == 'water' then
        local p = DRINK_PROP.water
        return DRINK_ANIM_BEER, p.bone, p.pos, p.rot, p.rotOrder
    end
    local p = DRINK_PROP.stein
    return DRINK_ANIM_BOTTLE, p.bone, p.pos, p.rot, p.rotOrder
end

--- SKEL_L_Hand — mp_player_int_eat_burger_fp (sph-frog ile aynı tutuş)
local FOOD_PROP = {
    default = { pos = vec3(0.13, 0.05, 0.02), rot = vec3(-80.0, 0.0, -20.0) },
    fruit   = { pos = vec3(0.16, 0.06, 0.02), rot = vec3(-75.0, 15.0, 35.0) },
    long    = { pos = vec3(0.11, 0.04, 0.02), rot = vec3(-80.0, 70.0, -20.0) },
}
local EAT_HOLD = FOOD_PROP.default.pos
local EAT_ROT = FOOD_PROP.default.rot

local function resolveFoodProp(pos, rot, tier)
    if pos or rot then
        return pos or FOOD_PROP.default.pos, rot or FOOD_PROP.default.rot
    end
    if tier == 'fresh' then
        return FOOD_PROP.fruit.pos, FOOD_PROP.fruit.rot
    end
    if tier == 'bread' then
        return FOOD_PROP.long.pos, FOOD_PROP.long.rot
    end
    return FOOD_PROP.default.pos, FOOD_PROP.default.rot
end

--- ox_inventory degrade = dakika (envantere girdiginde tazelik süresi baslar)
local FOOD_DEGRADE = {
    fresh  = 360,   -- 6 saat — çiğ meyve/sebze
    cooked = 480,   -- 8 saat — pişmiş yemek
    bread  = 720,   -- 12 saat — ekmek
    sweet  = 1440,  -- 24 saat — şeker/tatlı
    drink  = 360,   -- 6 saat — içecek
}

--- HUD açlık/susuzluk (0-100); yemek hunger ve içecek thirst aynı çarpan
local NEED_MULT = 2.0

local function needValue(amount)
    if not amount or amount <= 0 then return 0 end
    return math.min(100, math.floor(amount * NEED_MULT))
end

local function needStatus(hunger, thirst)
    local status = {}
    local h = needValue(hunger)
    local t = needValue(thirst)
    if h > 0 then status.hunger = h end
    if t > 0 then status.thirst = t end
    return status
end

local function foodItem(label, description, hunger, thirst, model, weight, usetime, image, pos, rot, tier)
    local status = needStatus(hunger, thirst)
    local hold, rotation = resolveFoodProp(pos, rot, tier)
    return {
        label = label,
        weight = weight or 80,
        stack = true,
        close = true,
        consume = 1,
        degrade = FOOD_DEGRADE[tier or 'cooked'] or FOOD_DEGRADE.cooked,
        decay = true,
        description = description,
        client = {
            image = image,
            status = status,
            anim = EAT_ANIM,
            prop = { model = model, bone = 18905, pos = hold, rot = rotation, rotOrder = 2 },
            usetime = usetime or 3000,
        },
    }
end

local function drinkClient(model, style, usetime, image, hunger, thirst)
    local anim, bone, pos, rot, rotOrder = resolveDrink(style)
    return {
        image = image,
        status = needStatus(hunger, thirst),
        anim = anim,
        prop = { model = model, bone = bone, pos = pos, rot = rot, rotOrder = rotOrder },
        usetime = usetime,
    }
end

local function drinkItem(label, description, thirst, hunger, model, weight, usetime, image, style)
    return {
        label = label,
        weight = weight or 200,
        stack = true,
        close = true,
        consume = 1,
        degrade = FOOD_DEGRADE.drink,
        decay = true,
        description = description,
        client = drinkClient(model, style, usetime or 3000, image, hunger, thirst),
    }
end

